function isValidCardNumber(input) {
  if (typeof input !== 'string') {
    return false;
  }

  // Check for invalid characters (anything other than digit, space, hyphen)
  if (!/^[0-9\s-]*$/.test(input)) {
    return false;
  }

  // Remove spaces and hyphens
  const cleaned = input.replace(/[\s-]/g, '');

  // Check length: must be between 12 and 19 digits
  if (cleaned.length < 12 || cleaned.length > 19) {
    return false;
  }

  // Luhn algorithm
  let sum = 0;
  let shouldDouble = false;

  // Iterate from right to left
  for (let i = cleaned.length - 1; i >= 0; i--) {
    let digit = parseInt(cleaned[i], 10);

    if (shouldDouble) {
      digit *= 2;
      if (digit > 9) {
        digit -= 9;
      }
    }

    sum += digit;
    shouldDouble = !shouldDouble;
  }

  return sum % 10 === 0;
}

module.exports = { isValidCardNumber };
