function render(template, data) {
  if (typeof template !== 'string') {
    throw new TypeError('template must be a string');
  }

  const placeholderPattern = /\{\{(\s*)(.*?)\s*}\}/g;

  return template.replace(placeholderPattern, (match, leadingWs, content) => {
    // If content is empty or contains invalid characters for a path
    if (!content || /[{}.\s]/.test(content)) {
      return match;
    }

    const segments = content.split('.');
    let current = data;

    for (const segment of segments) {
      if (current === null || current === undefined) {
        return '';
      }

      if (typeof current !== 'object') {
        return '';
      }

      // Check if segment is a valid index for array or own property for object
      const isArray = Array.isArray(current);
      const isIndex = isArray && /^\d+$/.test(segment);

      if (isIndex) {
        const index = Number(segment);
        if (index < 0 || index >= current.length) {
          return '';
        }
        current = current[index];
      } else if (current.hasOwnProperty(segment)) {
        current = current[segment];
      } else {
        return '';
      }
    }

    if (current === null || current === undefined) {
      return '';
    }

    return String(current);
  });
}

