function topoSort(graph) {
  if (graph === null || graph === undefined || typeof graph !== 'object') {
    return [];
  }

  // Collect all task names: keys in graph + all names in dependency lists
  const allTasks = new Set();
  for (const task in graph) {
    if (Object.prototype.hasOwnProperty.call(graph, task)) {
      allTasks.add(task);
      const deps = graph[task];
      if (Array.isArray(deps)) {
        for (const dep of deps) {
          allTasks.add(dep);
        }
      }
    }
  }

  // Build adjacency list (dependencies -> task) and in-degree map
  // We need to know which tasks depend on which.
  // graph[task] = list of tasks that must come BEFORE task.
  // So edges are: dep -> task
  const adj = {}; // adj[dep] = list of tasks that depend on dep
  const inDegree = {}; // inDegree[task] = number of unsatisfied dependencies

  for (const task of allTasks) {
    if (!adj.hasOwnProperty(task)) {
      adj[task] = [];
    }
    inDegree[task] = 0;
  }

  // Initialize inDegree and adj based on graph
  for (const task in graph) {
    if (Object.prototype.hasOwnProperty.call(graph, task)) {
      const deps = graph[task];
      if (Array.isArray(deps)) {
        const uniqueDeps = [...new Set(deps)]; // Handle duplicates
        inDegree[task] = uniqueDeps.length;
        for (const dep of uniqueDeps) {
          if (!adj[dep]) {
            adj[dep] = [];
          }
          adj[dep].push(task);
        }
      } else {
        inDegree[task] = 0;
      }
    }
  }

  // Find all tasks with inDegree 0
  const queue = [];
  for (const task of allTasks) {
    if (inDegree[task] === 0) {
      queue.push(task);
    }
  }

  // Sort the initial queue to ensure we pick the smallest first
  queue.sort();

  const result = [];
  let processedCount = 0;

  while (queue.length > 0) {
    // Pick the smallest task (queue is maintained sorted)
    const current = queue.shift();
    result.push(current);
    processedCount++;

    // If current has dependents, reduce their inDegree
    if (adj[current]) {
      for (const dependent of adj[current]) {
        inDegree[dependent]--;
        if (inDegree[dependent] === 0) {
          queue.push(dependent);
        }
      }
      // Re-sort to maintain order (since we might have added new tasks)
      // Optimization: we could use a priority queue, but for simplicity we sort
      queue.sort();
    }
  }

  if (processedCount !== allTasks.size) {
    throw new Error("cycle detected in dependencies");
  }

  return result;
}

