import re

def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    if not text:
        raise ValueError("Empty string is not a valid duration")

    # Check for whitespace, signs, or invalid characters early
    if any(c.isspace() for c in text):
        raise ValueError("Duration string must not contain whitespace")

    # Pattern to match one or more <integer><unit> parts
    # integer: one or more digits
    # unit: d, h, m, or s
    pattern = r'^(\d+[dhms])+$'
    if not re.match(pattern, text):
        raise ValueError("Invalid duration format")

    # Split into parts
    # We can use a regex to find all matches of <digits><unit>
    parts = re.findall(r'(\d+)([dhms])', text)

    if not parts:
        raise ValueError("No valid parts found")

    # Define unit values and order
    unit_values = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    unit_order = {'d': 0, 'h': 1, 'm': 2, 's': 3}

    last_order = -1
    total_seconds = 0

    for num_str, unit in parts:
        # Check for repeated units
        if unit in unit_values:
            current_order = unit_order[unit]
            if current_order < last_order:
                raise ValueError("Units must be in strictly descending order")
            if current_order == last_order:
                raise ValueError("Each unit may appear at most once")
            last_order = current_order
        else:
            raise ValueError(f"Unknown unit: {unit}")

        number = int(num_str)
        total_seconds += number * unit_values[unit]

    return total_seconds
