class LRUCache:
    def __init__(self, capacity):
        if not isinstance(capacity, int) or isinstance(capacity, bool):
            raise TypeError("capacity must be an integer")
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self._capacity = capacity
        self._storage = {}
        self._doubly_linked_list = DoublyLinkedList()

    def get(self, key, default=None):
        node = self._storage.get(key)
        if node is None:
            return default
        self._doubly_linked_list.move_to_end(node)
        return node.value

    def put(self, key, value):
        node = self._storage.get(key)
        if node is not None:
            node.value = value
            self._doubly_linked_list.move_to_end(node)
        else:
            if len(self._storage) == self._capacity:
                lru_node = self._doubly_linked_list.pop_head()
                del self._storage[lru_node.key]
            new_node = self._doubly_linked_list.append_node(key, value)
            self._storage[key] = new_node

    def __len__(self):
        return len(self._storage)

    def __contains__(self, key):
        return key in self._storage

    def keys(self):
        return self._doubly_linked_list.get_keys()


class _Node:
    def __init__(self, key, value):
        self.key = key
        self.value = value
        self.prev = None
        self.next = None


class DoublyLinkedList:
    def __init__(self):
        self.head = _Node(None, None)
        self.tail = _Node(None, None)
        self.head.next = self.tail
        self.tail.prev = self.head

    def move_to_end(self, node):
        self._remove(node)
        self._append(node)

    def _remove(self, node):
        node.prev.next = node.next
        node.next.prev = node.prev
        node.prev = None
        node.next = None

    def _append(self, node):
        last = self.tail.prev
        last.next = node
        node.prev = last
        node.next = self.tail
        self.tail.prev = node

    def append_node(self, key, value):
        node = _Node(key, value)
        self._append(node)
        return node

    def pop_head(self):
        if self.head.next == self.tail:
            return None
        node = self.head.next
        self._remove(node)
        return node

    def get_keys(self):
        result = []
        current = self.head.next
        while current != self.tail:
            result.append(current.key)
            current = current.next
        return result
