function topoSort(graph) {
  const inDegree = new Map();
  const adjList = new Map();

  // Collect all tasks (keys and values in dependency lists)
  const allTasks = new Set();
  for (const key in graph) {
    if (Object.prototype.hasOwnProperty.call(graph, key)) {
      allTasks.add(key);
      const deps = graph[key];
      for (const dep of deps) {
        allTasks.add(dep);
      }
    }
  }

  // Initialize inDegree and adjacency list
  for (const task of allTasks) {
    inDegree.set(task, 0);
    adjList.set(task, []);
  }

  // Build graph: edge from dependency -> task
  for (const key in graph) {
    if (Object.prototype.hasOwnProperty.call(graph, key)) {
      const deps = graph[key];
      // Use a Set to handle duplicates
      const uniqueDeps = [...new Set(deps)];
      for (const dep of uniqueDeps) {
        adjList.get(dep).push(key);
        inDegree.set(key, inDegree.get(key) + 1);
      }
    }
  }

  // Initialize queue with tasks that have no dependencies
  const queue = [];
  for (const task of allTasks) {
    if (inDegree.get(task) === 0) {
      queue.push(task);
    }
  }

  // Sort the initial queue to ensure we pick the smallest name
  queue.sort();

  const result = [];

  while (queue.length > 0) {
    // Pick the smallest task name
    queue.sort();
    const current = queue.shift();
    result.push(current);

    // Process neighbors
    const neighbors = adjList.get(current) || [];
    for (const neighbor of neighbors) {
      inDegree.set(neighbor, inDegree.get(neighbor) - 1);
      if (inDegree.get(neighbor) === 0) {
        queue.push(neighbor);
      }
    }
  }

  // Check for cycle
  if (result.length !== allTasks.size) {
    throw new Error("cycle detected in dependencies");
  }

  return result;
}

