        raise ValueError("repeated units")

    # Define order and values
    unit_order = {'d': 0, 'h': 1, 'm': 2, 's': 3}
    unit_values = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}

    total_seconds = 0
    last_order = -1

    for number_str, unit in parts:
        if unit not in unit_order:
            raise ValueError(f"unknown unit: {unit}")

        current_order = unit_order[unit]
        if current_order <= last_order:
            raise ValueError("units must be in strictly descending order")
        last_order = current_order

        number = int(number_str)
        total_seconds += number * unit_values[unit]

