function topoSort(graph) {
  const tasks = new Set();
  const inDegree = new Map();
  const adjacency = new Map();

  // Collect all tasks and build the graph
  for (const [task, deps] of Object.entries(graph)) {
    tasks.add(task);
    for (const dep of deps) {
      tasks.add(dep);
    }
  }

  // Initialize inDegree and adjacency for all tasks
  for (const task of tasks) {
    inDegree.set(task, 0);
    adjacency.set(task, []);
  }

  // Build edges: dep -> task (dep must come before task)
  for (const [task, deps] of Object.entries(graph)) {
    const uniqueDeps = [...new Set(deps)];
    for (const dep of uniqueDeps) {
      adjacency.get(dep).push(task);
      inDegree.set(task, inDegree.get(task) + 1);
    }
  }

  // Find all tasks with no dependencies
  const queue = [];
  for (const task of tasks) {
    if (inDegree.get(task) === 0) {
      queue.push(task);
    }
  }

  // Sort queue to ensure we pick the smallest name first
  queue.sort();

  const result = [];

  while (queue.length > 0) {
    // Pick the smallest task (queue is always kept sorted)
    const current = queue.shift();
    result.push(current);

    const nextTasks = adjacency.get(current);
    for (const next of nextTasks) {
      const newInDegree = inDegree.get(next) - 1;
      inDegree.set(next, newInDegree);
      if (newInDegree === 0) {
        queue.push(next);
      }
    }

    // Re-sort to maintain order for next iteration
    queue.sort();
  }

  // Check for cycles
  if (result.length !== tasks.size) {
    throw new Error('cycle detected');
  }

  return result;
}

