function topoSort(graph) {
  // Build the full set of tasks and their dependencies
  const tasks = new Set();
  const dependencies = {};

  // First pass: collect all tasks (keys and values)
  for (const task in graph) {
    tasks.add(task);
    const deps = graph[task];
    if (Array.isArray(deps)) {
      for (const dep of deps) {
        tasks.add(dep);
      }
    }
  }

  // Initialize dependencies map for all tasks
  for (const task of tasks) {
    const deps = graph[task];
    if (Array.isArray(deps)) {
      // Remove duplicates while preserving order doesn't matter, just unique set
      dependencies[task] = Array.from(new Set(deps));
    } else {
      dependencies[task] = [];
    }
  }

  // Kahn's algorithm with lexicographical selection
  const result = [];
  const inDegree = {};
  const available = [];

  for (const task of tasks) {
    inDegree[task] = dependencies[task].length;
    if (inDegree[task] === 0) {
      available.push(task);
    }
  }

  // Sort available initially to ensure we pick smallest
  available.sort();

  while (available.length > 0) {
    // Pick the smallest task
    const current = available.shift();
    result.push(current);

    // Find all tasks that depend on current
    for (const task of tasks) {
      if (dependencies[task].includes(current)) {
        inDegree[task]--;
        if (inDegree[task] === 0) {
          available.push(task);
        }
      }
    }

    // Re-sort available to maintain lexicographical order
    available.sort();
  }

  // Check for cycle
  if (result.length !== tasks.size) {
    throw new Error('cycle detected');
  }

  return result;
}

