function topoSort(graph) {
  const inDegree = new Map();
  const adjList = new Map();

  // Collect all tasks
  const allTasks = new Set();
  for (const [task, deps] of Object.entries(graph)) {
    allTasks.add(task);
    for (const dep of deps) {
      allTasks.add(dep);
    }
  }

  // Initialize inDegree and adjList for all tasks
  for (const task of allTasks) {
    inDegree.set(task, 0);
    adjList.set(task, []);
  }

  // Build graph: dep -> task (dep must come before task)
  for (const [task, deps] of Object.entries(graph)) {
    const uniqueDeps = [...new Set(deps)];
    for (const dep of uniqueDeps) {
      // dep -> task
      adjList.get(dep).push(task);
      inDegree.set(task, inDegree.get(task) + 1);
    }
  }

  // Initialize queue with tasks that have no dependencies
  const queue = [];
  for (const task of allTasks) {
    if (inDegree.get(task) === 0) {
      queue.push(task);
    }
  }

  // Sort queue to ensure we pick the smallest name first
  queue.sort();

  const result = [];
  while (queue.length > 0) {
    // Pick the smallest task
    const current = queue.shift();
    result.push(current);

    // Process neighbors
    const neighbors = adjList.get(current);
    for (const neighbor of neighbors) {
      const newDegree = inDegree.get(neighbor) - 1;
      inDegree.set(neighbor, newDegree);
      if (newDegree === 0) {
        queue.push(neighbor);
      }
    }

    // Re-sort queue to maintain order
    queue.sort();
  }

  if (result.length !== allTasks.size) {
    throw new Error("cycle detected");
  }

  return result;
}

