class LRUCache:
    """A Least Recently Used (LRU) cache implementation."""

    def __init__(self, capacity):
        if not isinstance(capacity, int) or isinstance(capacity, bool):
            raise TypeError("capacity must be an int")
        if capacity < 1:
            raise ValueError("capacity must be at least 1")

        self._capacity = capacity
        self._store = {}  # key -> node
        self._head = None  # least recently used
        self._tail = None  # most recently used
        self._size = 0

    def _move_to_tail(self, node):
        """Move a node to the tail (most recently used position)."""
        if node is self._tail:
            return

        # Unlink node
        if node.prev:
            node.prev.next = node.next
        else:
            self._head = node.next

        if node.next:
            node.next.prev = node.prev

        node.next = None
        node.prev = None

        # Link node to tail
        if self._tail:
            node.prev = self._tail
            self._tail.next = node
        else:
            self._head = node

        self._tail = node

    def _add_to_tail(self, key, value):
        """Add a new node to the tail."""
        node = {'key': key, 'value': value, 'prev': None, 'next': None}
        self._store[key] = node

        if self._tail:
            node.prev = self._tail
            self._tail.next = node
        else:
            self._head = node

        self._tail = node
        self._size += 1

    def _remove_head(self):
        """Remove the least recently used node (head)."""
        if not self._head:
            return

        key = self._head['key']
        del self._store[key]

        self._head = self._head['next']
        if self._head:
            self._head['prev'] = None
        else:
            self._tail = None

        self._size -= 1

    def get(self, key, default=None):
        """Return the value for key, marking it as most recently used."""
        if key not in self._store:
            return default

        node = self._store[key]
        self._move_to_tail(node)
        return node['value']

    def put(self, key, value):
        """Store value for key, marking it as most recently used."""
        if key in self._store:
            node = self._store[key]
            node['value'] = value
            self._move_to_tail(node)
        else:
            if self._size >= self._capacity:
                self._remove_head()
            self._add_to_tail(key, value)

    def __len__(self):
        """Return the number of stored keys."""
        return self._size

    def __contains__(self, key):
        """Check if key is present without changing recency order."""
        return key in self._store

    def keys(self):
        """Return a list of keys ordered from least to most recently used."""
        keys_list = []
        node = self._head
        while node:
            keys_list.append(node['key'])
            node = node['next']
        return keys_list
