    // Valid segment characters: anything except {, }, ., and whitespace
    // A path is valid if it consists of one or more segments separated by dots
    // and contains no whitespace or { or }

    // First, check if there are any disallowed characters in the path (whitespace, {, })
    if (/[{}\s]/.test(path)) {
