function camelToSnake(str) {
  if (typeof str !== 'string') {
    throw new TypeError('Argument must be a string');
  }

  if (!/[A-Z]/.test(str)) {
    return str;
  }

  // First, insert underscore between a lower-case letter or digit and an upper-case letter
  // Then, insert underscore between an upper-case letter and another upper-case letter
  // that is followed by a lower-case letter (end of acronym)
  let result = str
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1_$2');

  return result.toLowerCase();
}

