function parseQuery(qs) {
  if (typeof qs !== 'string') {
    throw new TypeError('qs must be a string');
  }

  // Remove leading '?' if present
  if (qs.startsWith('?')) {
    qs = qs.slice(1);
  }

  // Handle empty string
  if (qs === '') {
    return Object.create(null);
  }

  const result = Object.create(null);
  const pairs = qs.split('&');

  for (const pair of pairs) {
    if (pair === '') {
      continue; // Skip empty pairs
    }

    const eqIndex = pair.indexOf('=');
    let rawKey, rawValue;

    if (eqIndex === -1) {
      rawKey = pair;
      rawValue = '';
    } else {
      rawKey = pair.slice(0, eqIndex);
      rawValue = pair.slice(eqIndex + 1);
    }

    // Decode key and value
    const decodedKey = decodeURIComponent(rawKey.replace(/\+/g, ' '));
    const decodedValue = decodeURIComponent(rawValue.replace(/\+/g, ' '));

    // Skip if decoded key is empty
    if (decodedKey === '') {
      continue;
    }

    // Handle duplicate keys
    if (result.hasOwnProperty(decodedKey)) {
      // Convert to array if not already
      if (!Array.isArray(result[decodedKey])) {
        result[decodedKey] = [result[decodedKey]];
      }
      result[decodedKey].push(decodedValue);
    } else {
      result[decodedKey] = decodedValue;
    }
  }

  return result;
}

