  // Segment: run of chars excluding {, }, ., and whitespace.
  // We capture the path part to validate it later.
  const placeholderRegex = /\{\{\s*([^{}\s][^{}\s.]*(?:\.[^{}\s][^{}\s.]*)*)\s*\}\}/g;

