    // Each segment must not be empty and must not contain disallowed chars.
    // Our regex already ensures segments don't contain {, }, ., or whitespace.
    // We just need to ensure the path itself is not empty and doesn't have double dots.
    if (!path) return false;
    if (path.includes('..')) return false;
    const segments = path.split('.');
    return segments.length > 0 && segments.every(s => s.length > 0);
  };

