function topoSort(graph) {
  // Collect all tasks and build adjacency list and in-degree map
  const allTasks = new Set();
  const dependencies = {}; // task -> Set of tasks that must come before it
  const dependents = {};   // task -> Set of tasks that depend on it (for cycle detection if needed, though Kahn's algorithm handles it)

  // Initialize all known tasks
  for (const task of Object.keys(graph)) {
    allTasks.add(task);
    dependencies[task] = new Set(graph[task]);
    for (const dep of graph[task]) {
      allTasks.add(dep);
    }
  }

  // Ensure all tasks have an entry in dependencies, even if not keys in graph
  for (const task of allTasks) {
    if (!dependencies[task]) {
      dependencies[task] = new Set();
    }
  }

  // Calculate in-degrees (number of dependencies)
  const inDegree = {};
  for (const task of allTasks) {
    inDegree[task] = dependencies[task].size;
  }

  // Initialize the queue with tasks that have no dependencies
  const available = [];
  for (const task of allTasks) {
    if (inDegree[task] === 0) {
      available.push(task);
    }
  }

  // Sort available tasks to ensure we pick the smallest lexicographically
  available.sort();

  const result = [];

  while (available.length > 0) {
    // Pick the smallest task
    const current = available.shift();
    result.push(current);

    // Find all tasks that depend on current
    for (const task of allTasks) {
      if (dependencies[task].has(current)) {
        dependencies[task].delete(current);
        inDegree[task]--;
        if (inDegree[task] === 0) {
          available.push(task);
        }
      }
    }

    // Re-sort to maintain order for the next selection
    available.sort();
  }

  // Check for cycle
  if (result.length !== allTasks.size) {
    throw new Error('cycle detected');
  }

  return result;
}

