class LRUCache:
    """Least Recently Used (LRU) Cache implementation."""

    def __init__(self, capacity):
        if not isinstance(capacity, int):
            raise TypeError("capacity must be an int")
        if capacity < 1:
            raise ValueError("capacity must be at least 1")

        self.capacity = capacity
        self._cache = {}  # key -> node
        self._head = None  # Least recently used
        self._tail = None  # Most recently used
        self._size = 0

    def _add_to_tail(self, key, value):
        """Add a new node to the tail (most recently used)."""
        node = {'key': key, 'value': value, 'prev': None, 'next': None}
        self._cache[key] = node

        if self._tail is None:
            self._head = self._tail = node
        else:
            node['prev'] = self._tail
            self._tail['next'] = node
            self._tail = node

        self._size += 1

    def _remove_node(self, node):
        """Remove a node from the doubly linked list."""
        if node['prev']:
            node['prev']['next'] = node['next']
        else:
            self._head = node['next']

        if node['next']:
            node['next']['prev'] = node['prev']
        else:
            self._tail = node['prev']

        del self._cache[node['key']]
        self._size -= 1

    def _move_to_tail(self, node):
        """Move an existing node to the tail (mark as most recently used)."""
        # Remove from current position
        if node['prev']:
            node['prev']['next'] = node['next']
        else:
            self._head = node['next']

        if node['next']:
            node['next']['prev'] = node['prev']
        else:
            self._tail = node['prev']

        # Add to tail
        node['prev'] = self._tail
        node['next'] = None

        if self._tail:
            self._tail['next'] = node
        self._tail = node

        # Update head if list was empty after removal (shouldn't happen in practice)
        if self._head is None:
            self._head = node

    def get(self, key, default=None):
        """Return the value for key, marking it as most recently used. Return default if key is absent."""
        if key not in self._cache:
            return default

        node = self._cache[key]
        self._move_to_tail(node)
        return node['value']

    def put(self, key, value):
        """Store value for key, marking it as most recently used. Evict LRU if necessary."""
        if key in self._cache:
            # Update existing key
            node = self._cache[key]
            node['value'] = value
            self._move_to_tail(node)
        else:
            # Add new key
            if self._size >= self.capacity:
                # Evict least recently used (head)
                self._remove_node(self._head)
            self._add_to_tail(key, value)

    def __len__(self):
        """Return the number of stored keys."""
        return self._size

