        if (!inDegree[task]) inDegree[task] = 0;
        // dep must come before task
        // So task depends on dep: edge dep -> task
        // inDegree[task] counts how many deps task has
        // adjacency[dep] lists tasks that depend on dep
      }
      inDegree[task] = uniqueDeps.size;
    }
  }

