      const uniqueDeps = new Set(deps);
      for (const dep of uniqueDeps) {
        adjacency[dep].push(task);
      }
    }
  }

  // Initialize queue with tasks having 0 in-degree
  const queue = [];
  for (const task of allTasks) {
    if (inDegree[task] === 0) {
      queue.push(task);
    }
  }

  // Sort queue to start with lexicographically smallest
  queue.sort();

  const result = [];
  const processedCount = 0;

  while (queue.length > 0) {
    // Pick the smallest task from queue
    queue.sort();
    const current = queue.shift();
    result.push(current);

    // For each task that depends on current
    if (adjacency[current]) {
      for (const neighbor of adjacency[current]) {
        inDegree[neighbor]--;
        if (inDegree[neighbor] === 0) {
          queue.push(neighbor);
        }
      }
    }
  }

