def flatten(obj, sep="."):
    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    result = {}

    def _flatten(current, path):
        if not isinstance(current, dict) and not isinstance(current, list):
            # Leaf value (including empty dict/list if nested, tuples, sets, None, etc.)
            if path:
                key = sep.join(str(p) for p in path)
                result[key] = current
            return

        # Container: dict or list
        if isinstance(current, dict):
            if not current:
                # Empty dict as nested container -> leaf
                if path:
                    key = sep.join(str(p) for p in path)
                    result[key] = current
                return
            for k, v in current.items():
                new_path = path + [str(k)]
                _flatten(v, new_path)
        elif isinstance(current, list):
            if not current:
                # Empty list as nested container -> leaf
                if path:
                    key = sep.join(str(p) for p in path)
                    result[key] = current
                return
            for i, v in enumerate(current):
                new_path = path + [str(i)]
                _flatten(v, new_path)

    _flatten(obj, [])
    return result
