  const dependencies = new Map();
  for (const task of allTasks) {
    dependencies.set(task, new Set());
  }
  for (const [task, deps] of Object.entries(graph)) {
    const depSet = dependencies.get(task);
    for (const dep of deps) {
      depSet.add(dep);
    }
  }

  // Track in-degree (number of unsatisfied dependencies)
  const inDegree = new Map();
  for (const task of allTasks) {
    inDegree.set(task, dependencies.get(task).size);
  }

  const result = [];
  // Candidate pool: tasks with inDegree 0
  let candidates = [];
  for (const task of allTasks) {
    if (inDegree.get(task) === 0) {
      candidates.push(task);
    }
  }

  // Sort candidates initially
  candidates.sort();

