                if prefix:
                    new_prefix = f"{prefix}{sep}{key_str}"
                else:
                    new_prefix = key_str
                _flatten(value, new_prefix)

        # Process list
        if isinstance(current, list):
            for index, value in enumerate(current):
                if prefix:
                    new_prefix = f"{prefix}{sep}{index}"
                else:
                    new_prefix = str(index)
                _flatten(value, new_prefix)

