function deepEqual(a, b) {
  // Handle primitives and special cases
  if (a === b) {
    // 0 === -0 is true, NaN !== NaN
    // If they are strictly equal, they are deeply equal
    // Exception: NaN !== NaN, so we need to check NaN separately
    if (Number.isNaN(a) && Number.isNaN(b)) {
      return true;
    }
    return true;
  }

  // If one is null and the other isn't, or one is a primitive and the other an object
  if (a == null || b == null) {
    return false;
  }

  const typeA = typeof a;
  const typeB = typeof b;

  if (typeA !== typeB) {
    return false;
  }

  // Functions: only equal if strictly equal (handled by initial === check)
  if (typeA === 'function') {
    return false;
  }

  // Dates
  if (a instanceof Date && b instanceof Date) {
    return a.getTime() === b.getTime();
  }

  // If one is Date and other isn't (or neither is), they are not equal
  if (a instanceof Date || b instanceof Date) {
    return false;
  }

  // Arrays
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) {
      return false;
    }
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i])) {
        return false;
      }
    }
    return true;
  }

  // If one is array and other isn't
  if (Array.isArray(a) || Array.isArray(b)) {
    return false;
  }

  // Plain Objects
  if (typeA === 'object' && typeB === 'object') {
    const keysA = Object.keys(a);
    const keysB = Object.keys(b);

    if (keysA.length !== keysB.length) {
      return false;
    }

    for (const key of keysA) {
      if (!Object.prototype.hasOwnProperty.call(b, key)) {
        return false;
      }
      if (!deepEqual(a[key], b[key])) {
        return false;
      }
    }

    return true;
  }

  return false;
}

