function formatBytes(n) {
  if (typeof n !== 'number' || !Number.isFinite(n)) {
    throw new TypeError('n must be a finite number');
  }
  if (n < 0 || !Number.isInteger(n)) {
    throw new RangeError('n must be a non-negative integer');
  }

  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let size = n;
  let unitIndex = 0;

  while (size >= 1024 && unitIndex < units.length - 1) {
    size /= 1024;
    unitIndex++;
  }

  // Round to at most one decimal place
  let formattedSize;
  if (Number.isInteger(size)) {
    formattedSize = String(size);
  } else {
    const rounded = Math.round(size * 10) / 10;
    // Check if rounding pushed us to 1024 and we can move up
    if (rounded === 1024 && unitIndex < units.length - 1) {
      formattedSize = '1';
      unitIndex++;
    } else {
      // Remove trailing .0 if present
      formattedSize = rounded % 1 === 0 ? String(Math.round(rounded)) : String(rounded);
    }
  }

  return `${formattedSize} ${units[unitIndex]}`;
}

module.exports = { formatBytes };
