function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  if (spec.trim() === '') {
    return [];
  }

  const parts = spec.split(',');
  const result = new Set();

  for (const part of parts) {
    const trimmed = part.trim();

    if (trimmed === '') {
      throw new SyntaxError('empty part or leading/trailing comma');
    }

    if (trimmed.includes('-')) {
      if (trimmed.split('-').length !== 2) {
        throw new SyntaxError('more than one dash');
      }

      const [loStr, hiStr] = trimmed.split('-');

      if (loStr === '' || hiStr === '') {
        throw new SyntaxError('missing end or start in range');
      }

      if (!/^\d+$/.test(loStr) || !/^\d+$/.test(hiStr)) {
        throw new SyntaxError('invalid characters or negative number');
      }

      const lo = parseInt(loStr, 10);
      const hi = parseInt(hiStr, 10);

      if (lo > hi) {
        throw new RangeError('range start is greater than end');
      }

      for (let i = lo; i <= hi; i++) {
        result.add(i);
      }
    } else {
      if (!/^\d+$/.test(trimmed)) {
        throw new SyntaxError('invalid number format');
      }

      const num = parseInt(trimmed, 10);
      result.add(num);
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

module.exports = { expandRanges };

