function deepEqual(a, b) {
  // Handle primitives and NaN
  if (a === b) {
    // 0 === -0 is true, which is correct per requirements
    // NaN === NaN is false, handled below
    return true;
  }
  if (Number.isNaN(a) && Number.isNaN(b)) {
    return true;
  }

  // If one is null and the other is not (or both are different non-null objects/functions)
  if (a == null || b == null) {
    return a === b;
  }

  // Check types
  const typeA = typeof a;
  const typeB = typeof b;

  if (typeA !== typeB) {
    return false;
  }

  // Functions: must be the same reference
  if (typeA === 'function') {
    return a === b;
  }

  // Handle Arrays
  if (Array.isArray(a)) {
    if (!Array.isArray(b)) return false;
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i])) return false;
    }
    return true;
  }

  // Handle Dates
  if (a instanceof Date) {
    if (!(b instanceof Date)) return false;
    return a.getTime() === b.getTime();
  }

  // Handle Plain Objects
  if (typeA === 'object') {
    const keysA = Object.keys(a);
    const keysB = Object.keys(b);

    if (keysA.length !== keysB.length) return false;

    for (const key of keysA) {
      if (!Object.prototype.hasOwnProperty.call(b, key)) {
        return false;
      }
      if (!deepEqual(a[key], b[key])) {
        return false;
      }
    }

    return true;
  }

  // Fallback for any other types (shouldn't be reached given logic above)
  return false;
}

