function deepEqual(a, b) {
  // Handle primitives
  if (typeof a !== 'object' || a === null) {
    if (typeof b !== 'object' || b === null) {
      // Handle NaN: NaN !== NaN, but we want them to be equal
      if (Number.isNaN(a) && Number.isNaN(b)) return true;
      // Handle -0 and 0: 0 === -0 is true, but 1/0 === 1/-0 is false (Infinity vs -Infinity)
      // However, the rule says 0 and -0 are equal. Standard === treats them as equal.
      // So standard === works for 0 and -0.
      return a === b;
    }
    return false;
  }

  // If a is object and b is not (or null)
  if (typeof b !== 'object' || b === null) {
    return false;
  }

  // Handle Functions
  if (typeof a === 'function') {
    return a === b;
  }

  // Handle Dates
  if (a instanceof Date) {
    if (!(b instanceof Date)) return false;
    return a.getTime() === b.getTime();
  }

  // Handle Arrays
  if (Array.isArray(a)) {
    if (!Array.isArray(b)) return false;
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i])) return false;
    }
    return true;
  }

  // Handle Plain Objects
  // Get own enumerable keys
  const keysA = Object.keys(a);
  const keysB = Object.keys(b);

  if (keysA.length !== keysB.length) return false;

  for (const key of keysA) {
    if (!Object.prototype.hasOwnProperty.call(b, key)) return false;
    if (!deepEqual(a[key], b[key])) return false;
  }

  return true;
}

