function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const trimmed = spec.trim();
  if (trimmed === '') {
    return [];
  }

  const parts = trimmed.split(',');
  const result = new Set();

  for (const part of parts) {
    if (part === '') {
      throw new SyntaxError('Empty part detected');
    }

    const dashIndex = part.indexOf('-');

    if (dashIndex === -1) {
      // Single number
      if (!/^\d+$/.test(part)) {
        throw new SyntaxError('Invalid number format: ' + part);
      }
      const num = parseInt(part, 10);
      result.add(num);
    } else {
      // Range lo-hi
      if (part.indexOf('-', dashIndex + 1) !== -1) {
        throw new SyntaxError('Multiple dashes detected: ' + part);
      }

      const loStr = part.substring(0, dashIndex);
      const hiStr = part.substring(dashIndex + 1);

      if (loStr === '' || hiStr === '') {
        throw new SyntaxError('Missing range endpoint: ' + part);
      }

      if (!/^\d+$/.test(loStr) || !/^\d+$/.test(hiStr)) {
        throw new SyntaxError('Invalid range format: ' + part);
      }

      const lo = parseInt(loStr, 10);
      const hi = parseInt(hiStr, 10);

      if (lo > hi) {
        throw new RangeError('Range start greater than end: ' + part);
      }

      for (let i = lo; i <= hi; i++) {
        result.add(i);
      }
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

