def spiral_order(matrix):
    if not matrix:
        return []

    rows = len(matrix)
    cols = len(matrix[0])

    # Check for empty rows or inconsistent lengths
    if cols == 0:
        return []

    for row in matrix:
        if len(row) != cols:
            raise ValueError("All rows must have the same length")

    result = []
    top, bottom = 0, rows - 1
    left, right = 0, cols - 1

