  let value = n;
  let unitIndex = 0;

  while (value >= 1024 && unitIndex < units.length - 1) {
    value /= 1024;
    unitIndex++;
  }

  // Round to at most one decimal place
  let rounded = Math.round(value * 10) / 10;

  // If rounding resulted in 1024 and we can go up a unit, do so
  if (rounded === 1024 && unitIndex < units.length - 1) {
    rounded = 1;
    unitIndex++;
  }

  // Format the number
  const formattedNumber = rounded % 1 === 0 ? String(Math.round(rounded)) : String(rounded);

  return `${formattedNumber} ${units[unitIndex]}`;
}

