function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const trimmed = spec.trim();
  if (trimmed === '') {
    return [];
  }

  const parts = trimmed.split(',');
  const result = new Set();

  for (const part of parts) {
    if (part === '') {
      throw new SyntaxError('Empty part found');
    }

    const dashIndex = part.indexOf('-');

    if (dashIndex === -1) {
      // Single number
      if (!/^\d+$/.test(part)) {
        throw new SyntaxError('Invalid number format');
      }
      const num = Number(part);
      result.add(num);
    } else {
      // Range
      if (part.indexOf('-', dashIndex + 1) !== -1) {
        throw new SyntaxError('More than one dash found');
      }

      if (dashIndex === 0) {
        throw new SyntaxError('Missing start of range');
      }
      if (dashIndex === part.length - 1) {
        throw new SyntaxError('Missing end of range');
      }

      const startStr = part.slice(0, dashIndex);
      const endStr = part.slice(dashIndex + 1);

      if (!/^\d+$/.test(startStr) || !/^\d+$/.test(endStr)) {
        throw new SyntaxError('Invalid range format');
      }

      const start = Number(startStr);
      const end = Number(endStr);

      if (start > end) {
        throw new RangeError('Range start must not exceed end');
      }

      for (let i = start; i <= end; i++) {
        result.add(i);
      }
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

module.exports = { expandRanges };
