def spiral_order(matrix):
    if not matrix:
        return []

    rows = len(matrix)
    cols = len(matrix[0])

    if cols == 0:
        # Check if all rows are empty (consistent length 0)
        if any(len(row) != 0 for row in matrix):
            raise ValueError("rows do not all have the same length")
        return []

    # Validate consistent row lengths
    for row in matrix:
        if len(row) != cols:
            raise ValueError("rows do not all have the same length")

    result = []
    top, bottom = 0, rows - 1
    left, right = 0, cols - 1

    while top <= bottom and left <= right:
        # Traverse right along the top row
        for col in range(left, right + 1):
            result.append(matrix[top][col])
        top += 1

        # Traverse down along the right column
        if top <= bottom:
            for row in range(top, bottom + 1):
                result.append(matrix[row][right])
            right -= 1

        # Traverse left along the bottom row
        if left <= right and top <= bottom:
            for col in range(right, left - 1, -1):
                result.append(matrix[bottom][col])
            bottom -= 1

        # Traverse up along the left column
        if top <= bottom and left <= right:
            for row in range(bottom, top - 1, -1):
                result.append(matrix[row][left])
            left += 1

    return result
