    if (typeof fn !== 'function') {
      throw new TypeError('fn must be a function');
    }
    const listeners = this._getListeners(event);
    listeners.push({ fn, once: true });
    return this;
  }

  off(event, fn) {
    const listeners = this._getListeners(event);
    const newListeners = listeners.filter((listener) => listener.fn !== fn);
    if (newListeners.length === listeners.length) {
      return this;
    }
    this._listeners.set(event, newListeners);
    return this;
  }

  emit(event, ...args) {
    let calledAny = false;
    const listeners = this._getListeners(event);
    const snapshot = listeners.map((l) => l);

    for (const item of snapshot) {
      if (item.once) {
        this.off(event, item.fn);
      }
      item.fn.call(this, ...args);
      calledAny = true;
    }

