function formatBytes(n) {
  if (typeof n !== 'number' || !Number.isFinite(n)) {
    throw new TypeError('n must be a finite number');
  }
  if (n < 0 || !Number.isInteger(n)) {
    throw new RangeError('n must be a non-negative integer');
  }

  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let value = n;
  let unitIndex = 0;

  while (value >= 1024 && unitIndex < units.length - 1) {
    value /= 1024;
    unitIndex++;
  }

  // Round to 1 decimal place
  let formattedValue = Math.round(value * 10) / 10;

  // Check if rounding caused overflow to next unit
  if (formattedValue === 1024 && unitIndex < units.length - 1) {
    formattedValue = 1;
    unitIndex++;
  }

  // Format number: remove decimal if .0
  const stringValue = formattedValue % 1 === 0 ? formattedValue.toString() : formattedValue.toFixed(1);

  return `${stringValue} ${units[unitIndex]}`;
}

module.exports = { formatBytes };
