      // Remove once listeners before calling
      if (entry.once) {
        this.off(event, entry.fn);
      }
      entry.fn.apply(this, args);
      called = true;
    }

    return called;
  }

  listenerCount(event) {
    const listeners = this._listeners.get(event);
    return listeners ? listeners.length : 0;
  }
}

