function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',');
  const result = new Set();

  for (const part of parts) {
    const trimmed = part.trim();
    if (trimmed === '') {
      throw new SyntaxError('Empty part is not allowed');
    }

    const dashIndex = trimmed.indexOf('-');
    let start, end;

    if (dashIndex === -1) {
      // Single number
      if (!/^\d+$/.test(trimmed)) {
        throw new SyntaxError('Invalid part: contains non-digit characters');
      }
      start = parseInt(trimmed, 10);
      end = start;
    } else {
      // Range
      if (dashIndex === 0 || dashIndex === trimmed.length - 1) {
        throw new SyntaxError('Range must have both start and end numbers');
      }
      if (trimmed.indexOf('-', dashIndex + 1) !== -1) {
        throw new SyntaxError('Range contains more than one dash');
      }

      const startStr = trimmed.slice(0, dashIndex);
      const endStr = trimmed.slice(dashIndex + 1);

      if (!/^\d+$/.test(startStr) || !/^\d+$/.test(endStr)) {
        throw new SyntaxError('Range parts must be non-negative integers');
      }

      start = parseInt(startStr, 10);
      end = parseInt(endStr, 10);

      if (start > end) {
        throw new RangeError('Range start must not be greater than end');
      }
    }

    for (let i = start; i <= end; i++) {
      result.add(i);
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

module.exports = { expandRanges };
