import re

def compare_versions(a, b):
    """
    Compares two Semantic Versioning 2.0.0 strings.
    Returns -1 if a < b, 0 if a == b, 1 if a > b.
    Raises ValueError if either string is invalid.
    """
    def parse_version(version_str):
        # Regex pattern for Semantic Versioning 2.0.0
        # Core: MAJOR.MINOR.PATCH
        # Optional: -PRERELEASE
        # Optional: +BUILD
        pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$'

        match = re.match(pattern, version_str)
        if not match:
            raise ValueError(f"Invalid version string: {version_str}")

        major = int(match.group(1))
        minor = int(match.group(2))
        patch = int(match.group(3))
        prerelease = match.group(4)
        # build = match.group(5)  # Ignored as per requirements

        return {
            'major': major,
            'minor': minor,
            'patch': patch,
            'prerelease': prerelease
        }

    def compare_prerelease(pre_a, pre_b):
        # A version with no prerelease has higher precedence than one with a prerelease
        if pre_a is None and pre_b is None:
            return 0
        if pre_a is None:
            return 1  # a has no prerelease, b has one -> a > b
        if pre_b is None:
            return -1 # a has prerelease, b has no one -> a < b

        ids_a = pre_a.split('.')
        ids_b = pre_b.split('.')

        # Compare identifier by identifier
        for id_a, id_b in zip(ids_a, ids_b):
            # Check if identifiers are numeric
            is_a_digit = id_a.isdigit()
            is_b_digit = id_b.isdigit()

            if is_a_digit and is_b_digit:
                # Compare numerically
                num_a = int(id_a)
                num_b = int(id_b)
                if num_a < num_b:
                    return -1
                if num_a > num_b:
                    return 1
            else:
                # Lexical comparison
                if is_a_digit and not is_b_digit:
                    # Numeric has lower precedence than alphanumeric
                    return -1
                if not is_a_digit and is_b_digit:
                    return 1

                # Both are alphanumeric (or mixed), compare lexically
                if id_a < id_b:
                    return -1
                if id_a > id_b:
                    return 1

        # If all shared identifiers are equal, the one with more identifiers has higher precedence
        if len(ids_a) < len(ids_b):
            return -1
        if len(ids_a) > len(ids_b):
            return 1

        return 0

    try:
        v_a = parse_version(a)
        v_b = parse_version(b)
    except ValueError:
        raise

    # Compare MAJOR
    if v_a['major'] != v_b['major']:
        return 1 if v_a['major'] > v_b['major'] else -1

    # Compare MINOR
    if v_a['minor'] != v_b['minor']:
        return 1 if v_a['minor'] > v_b['minor'] else -1

    # Compare PATCH
    if v_a['patch'] != v_b['patch']:
        return 1 if v_a['patch'] > v_b['patch'] else -1

    # Compare PRERELEASE
    return compare_prerelease(v_a['prerelease'], v_b['prerelease'])
