  for (const part of parts) {
    if (part === '') {
      throw new SyntaxError('Empty part detected');
    }

    const dashIndex = part.indexOf('-');

    if (dashIndex === -1) {
      // Single number
      if (!/^\d+$/.test(part)) {
        throw new SyntaxError('Invalid number format');
      }
      const num = parseInt(part, 10);
      result.add(num);
    } else {
      // Range
      if (part.indexOf('-', dashIndex + 1) !== -1) {
        throw new SyntaxError('More than one dash in range');
      }

      const startStr = part.slice(0, dashIndex);
      const endStr = part.slice(dashIndex + 1);

      if (startStr === '' || endStr === '') {
        throw new SyntaxError('Missing start or end in range');
      }

      if (!/^\d+$/.test(startStr) || !/^\d+$/.test(endStr)) {
        throw new SyntaxError('Invalid number format in range');
      }

      const start = parseInt(startStr, 10);
      const end = parseInt(endStr, 10);

      if (start > end) {
        throw new RangeError('Range start must not be greater than end');
      }

      for (let i = start; i <= end; i++) {
        result.add(i);
      }
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

