def wrap_text(text, width):
    if not isinstance(width, int) or isinstance(width, bool):
        raise TypeError("width must be an int")
    if width < 1:
        raise ValueError("width must be at least 1")

    words = text.split()
    if not words:
        return []

    lines = []
    current_line = []
    current_length = 0

    for word in words:
        word_len = len(word)
        # Length if we add this word to the current line
        # If current_line is empty, no space needed, otherwise +1 for space
        potential_length = current_length + (1 if current_line else 0) + word_len

        if potential_length <= width:
            # Add word to current line
            current_line.append(word)
            current_length = potential_length
        else:
            # Current line is full, start a new line
            if current_line:
                lines.append(" ".join(current_line))

            # If the word itself is longer than width, it goes on a line by itself
            if word_len > width:
                lines.append(word)
                current_line = []
                current_length = 0
            else:
                current_line = [word]
                current_length = word_len

    # Append the last line if it has any words
    if current_line:
        lines.append(" ".join(current_line))

