            # Enter string literal
            i += 1
            while i < n:
                c = code[i]
                if c == '\\':
                    # Skip the escaped character
                    i += 2
                elif c == '"':
                    # End of string
                    i += 1
                    break
                else:
                    i += 1
            else:
                # String never closed
                return False
        elif char in '([{':
            stack.append(char)
            i += 1
        elif char in ')]}':
            if not stack:
                return False
            last = stack.pop()
            if (char == ')' and last != '(') or \
               (char == ']' and last != '[') or \
               (char == '}' and last != '{'):
                return False
            i += 1
        else:
            i += 1

    return len(stack) == 0

