import re

def to_24h(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    text = text.strip()
    if not text:
        raise ValueError("text cannot be empty")

    # Pattern: H or HH, colon, MM, optional single space, AM/PM (case insensitive)
    pattern = r'^(\d{1,2}):(\d{2})(\s?)(AM|PM)$'
    match = re.match(pattern, text, re.IGNORECASE)
    if not match:
        raise ValueError("invalid format")

    hour_str, minute_str, _, suffix = match.groups()
    suffix = suffix.upper()

    hour = int(hour_str)
    minute = int(minute_str)

    if hour < 1 or hour > 12:
        raise ValueError("hour must be between 1 and 12")
    if minute < 0 or minute > 59:
        raise ValueError("minutes must be between 00 and 59")

    if suffix == "AM":
        if hour == 12:
            hour = 0
    elif suffix == "PM":
        if hour != 12:
            hour += 12
    else:
        raise ValueError("suffix must be AM or PM")

    return f"{hour:02d}:{minute:02d}"
