      const cell = rows[i][j] === null || rows[i][j] === undefined ? "" : String(rows[i][j]);
      if (cell.length > colWidths[j]) {
        colWidths[j] = cell.length;
      }
    }
  }

  const lines = [];

  for (let i = 0; i < rows.length; i++) {
    const lineCells = [];
    for (let j = 0; j < numCols; j++) {
      let cell;
      if (j < rows[i].length) {
        cell = rows[i][j] === null || rows[i][j] === undefined ? "" : String(rows[i][j]);
      } else {
        cell = "";
      }
      lineCells.push(cell);
