def is_balanced(code):
    stack = []
    i = 0
    n = len(code)

    while i < n:
        char = code[i]

        # Handle string literals
        if char == '"':
            i += 1
            while i < n:
                if code[i] == '\\' and i + 1 < n:
                    # Skip escaped character
                    i += 2
                elif code[i] == '"':
                    # End of string
                    i += 1
                    break
                else:
                    i += 1
            else:
                # String never closed
                return False
            continue

        # Check for opening brackets
        if char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack:
                return False
            last = stack.pop()
            if (char == ')' and last != '(') or \
               (char == ']' and last != '[') or \
               (char == '}' and last != '{'):
                return False

        i += 1

    return len(stack) == 0

