    words = text.split()
    if not words:
        return []

    lines = []
    current_line = []
    current_length = 0

    for word in words:
        word_len = len(word)
        # Length if we add this word to the current line
        # If current_line is empty, length is word_len
        # Otherwise, it's current_length + 1 (space) + word_len
        if current_line:
            new_length = current_length + 1 + word_len
        else:
            new_length = word_len

        # If the word fits, or if the line is empty and word is too long (handled below)
        if new_length <= width:
            if current_line:
                current_line.append(" ")
            current_line.append(word)
            current_length = new_length
        else:
            # Word doesn't fit
