                # Finalize current line
                lines.append("".join(current_line))
                current_line = [word]
                current_length = word_len
            else:
                # Line is empty, but word is longer than width
                # Put it on a line by itself
                lines.append(word)
                current_line = []
                current_length = 0

    if current_line:
        lines.append("".join(current_line))

