def wrap_text(text, width):
    if not isinstance(width, int):
        raise TypeError("width must be an integer")
    if width < 1:
        raise ValueError("width must be at least 1")

    import re
    words = re.split(r'\s+', text.strip())
    if not words:
        return []

    lines = []
    current_line = []
    current_length = 0

    for word in words:
        word_len = len(word)
        # Length if we add this word to current line
        # If current_line is empty, length is word_len
        # Otherwise, it's current_length + 1 (space) + word_len
        if current_line:
            new_length = current_length + 1 + word_len
        else:
            new_length = word_len

        if new_length <= width:
            current_line.append(word)
            current_length = new_length
        else:
            # Word doesn't fit; finish current line if any
            if current_line:
                lines.append(' '.join(current_line))

            # If word is longer than width, it goes alone
            if word_len > width:
                lines.append(word)
                current_line = []
                current_length = 0
            else:
                # Start new line with this word
                current_line = [word]
                current_length = word_len

    if current_line:
        lines.append(' '.join(current_line))

    return lines
