    cols = len(grid[0])

    # Validate row lengths
    for row in grid:
        if len(row) != cols:
            raise ValueError("All rows must have the same length")

    valid_chars = {'S', 'E', '#', '.'}
    start_pos = None
    end_pos = None

    # Validate characters and find start/end
    for r in range(rows):
        for c in range(cols):
            char = grid[r][c]
            if char not in valid_chars:
                raise ValueError(f"Invalid character: {char}")
            if char == 'S':
                if start_pos is not None:
                    raise ValueError("Multiple 'S' found")
                start_pos = (r, c)
            elif char == 'E':
                if end_pos is not None:
                    raise ValueError("Multiple 'E' found")
                end_pos = (r, c)

    if start_pos is None:
        raise ValueError("No 'S' found in grid")
    if end_pos is None:
        raise ValueError("No 'E' found in grid")

    # BFS to find shortest path
    queue = deque([(start_pos, 0)])
    visited = {start_pos}
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        (r, c), steps = queue.popleft()

        if (r, c) == end_pos:
            return steps

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in visited and grid[nr][nc] != '#':
                    visited.add((nr, nc))
                    queue.append(((nr, nc), steps + 1))

    return -1
