            raise ValueError
        days_in_month = monthrange(year, month)[1]
        if day > days_in_month:
            raise ValueError
    except (ValueError, OverflowError):
        raise ValueError("Invalid date")

    # Calculate new year and month
    total_months = year * 12 + (month - 1) + n
    new_year = total_months // 12
    new_month = (total_months % 12) + 1

    # Validate result year range
    if not (1 <= new_year <= 9999):
        raise ValueError("Result year out of range (1..9999)")

    # Determine the new day, clamping to the last day of the new month if necessary
    try:
        days_in_new_month = monthrange(new_year, new_month)[1]
    except (ValueError, OverflowError):
        raise ValueError("Invalid date calculation")

    new_day = min(day, days_in_new_month)

    return f"{new_year:04d}-{new_month:02d}-{new_day:02d}"
