    # BFS to find shortest path
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right
    visited = [[False] * cols for _ in range(rows)]

    queue = deque()
    queue.append((start_pos[0], start_pos[1], 0))  # (row, col, steps)
    visited[start_pos[0]][start_pos[1]] = True

    while queue:
